 "content": "from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    boxes = {}
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if cells:
            r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
            c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
            boxes[color] = (r0, r1, c0, c1)

    def interior_count(color, box):
        r0, r1, c0, c1 = box
        return sum(grid[r][c] == color for r in range(r0 + 1, r1) for c in range(c0 + 1, c1))

    # The patterned rectangle is the template; the other rectangles are empty frames.
    patterned = [(interior_count(color, box), color, box) for color, box in boxes.items()
                 if interior_count(color, box) > 0]
    if not patterned:
        return [row[:] for row in grid]
    _, source, sb = max(patterned)
    sr0, sr1, sc0, sc1 = sb
    sh, sw = sr1 - sr0 + 1, sc1 - sc0 + 1
    out = [[0] * w for _ in range(h)]

    # Keep the source pattern intact, and replicate it only into same-sized frames.
    for color, (r0, r1, c0, c1) in boxes.items():
        if (r1 - r0 + 1, c1 - c0 + 1) != (sh, sw):
            continue
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if color == source:
                    out[r][c] = grid[r][c]
                elif r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color
                elif grid[sr0 + (r - r0)][sc0 + (c - c0)] == source:
                    out[r][c] = color
    return out
